/**
 * Native app-lifecycle bridge.
 *
 * In a Capacitor WKWebView the browser `focus` / `visibilitychange` events
 * do NOT fire reliably when the app returns to the foreground, so
 * TanStack Query's `refetchOnWindowFocus: true` (see queryClient.ts) is
 * effectively dead on iOS — returning to the app shows stale jobs/messages/
 * balances until staleTime + a remount. This hook bridges Capacitor's
 * `appStateChange` into TanStack's `focusManager` so the existing config
 * actually fires a background refetch on foreground. It also clears
 * delivered notification banners when the app becomes active so the
 * Notification Center doesn't pile up after the user has already opened the
 * app (the numeric icon badge is owned by MobileNav, which pins it to the
 * live unread count), and feeds @capacitor/network into TanStack's
 * `onlineManager` so queries
 * pause/refetch on real OS reachability rather than the flaky WKWebView
 * navigator.onLine signal.
 *
 * No-op on web (the browser events already work there).
 */
import { useEffect } from "react";
import { focusManager, onlineManager } from "@tanstack/react-query";
import { isNativePlatform } from "@/lib/nativeInit";
import { report } from "@/lib/errorLogger";

let attached = false;
let networkAttached = false;

async function clearDeliveredNotifications() {
  try {
    const { PushNotifications } = await import("@capacitor/push-notifications");
    await PushNotifications.removeAllDeliveredNotifications();
  } catch {
    /* best-effort — never break foreground on a badge cleanup failure */
  }
}

export function useAppLifecycle() {
  useEffect(() => {
    if (!isNativePlatform || attached) return;
    attached = true;

    let removeListener: (() => void) | undefined;
    void (async () => {
      try {
        const { App } = await import("@capacitor/app");
        const handle = await App.addListener("appStateChange", ({ isActive }) => {
          focusManager.setFocused(isActive);
          if (isActive) {
            // Clear stacked notification banners from the Notification
            // Center, but leave the numeric icon badge alone — MobileNav
            // owns it and keeps it pinned to the live unread count (so the
            // badge reflects unread messages, not just "app was opened").
            void clearDeliveredNotifications();
          }
        });
        removeListener = () => {
          void handle.remove();
        };
      } catch (err) {
        report(err, { tags: { source: "useAppLifecycle" } });
      }
    })();

    return () => {
      removeListener?.();
      attached = false;
    };
  }, []);

  // Feed @capacitor/network into TanStack's onlineManager so queries pause
  // while offline and refetch the moment connectivity returns. The default
  // onlineManager relies on the window online/offline events, which — like
  // navigator.onLine — are unreliable inside a WKWebView; the Network plugin
  // reports real OS reachability. Web is left on the TanStack default.
  useEffect(() => {
    if (!isNativePlatform || networkAttached) return;
    networkAttached = true;

    let removeListener: (() => void) | undefined;
    void (async () => {
      try {
        const { Network } = await import("@capacitor/network");
        const initial = await Network.getStatus();
        onlineManager.setOnline(initial.connected);
        const handle = await Network.addListener("networkStatusChange", (s) => {
          onlineManager.setOnline(s.connected);
        });
        removeListener = () => void handle.remove();
      } catch (err) {
        report(err, { tags: { source: "useAppLifecycle.network" } });
      }
    })();

    return () => {
      removeListener?.();
      networkAttached = false;
    };
  }, []);
}
